<script setup>
import {computed,onMounted,ref} from 'vue';
import {useRoute} from 'vue-router';
import Icon from '../components/Icon.vue';
import Quantity from '../components/Quantity.vue';
import {api,state,money,cartCount,cartTotal,addToCart,changeQuantity} from '../lib';
const route=useRoute(),menus=ref([]),category=ref('all'),loading=ref(true),error=ref('');
const categories=[{id:'all',name:'Semua menu',icon:'UtensilsCrossed'},{id:'makanan',name:'Makanan',icon:'UtensilsCrossed'},{id:'minuman',name:'Minuman',icon:'Coffee'},{id:'camilan',name:'Camilan',icon:'Cookie'}];
const filtered=computed(()=>menus.value.filter(x=>category.value==='all'||x.category===category.value));
const quantity=id=>state.cart.find(x=>x.id===id)?.quantity||0;
const openNow=computed(()=>{const parts=new Intl.DateTimeFormat('en-GB',{weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Asia/Jakarta'}).formatToParts(new Date());const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));const minutes=Number(p.hour)*60+Number(p.minute);return !['Sat','Sun'].includes(p.weekday)&&minutes>=510&&minutes<960;});
async function load(){loading.value=true;error.value='';try{menus.value=await api('/menu');}catch(e){error.value=e.message;}finally{loading.value=false;}}
onMounted(()=>{const table=Number(route.query.meja);if(Number.isInteger(table)&&table>0&&table<=50){state.table=table;state.orderType='dine_in';}load();});
</script>
<template>
  <div class="container menu-page">
    <section class="cafe-hero">
      <div class="hero-copy"><div class="eyebrow"><span class="tiny-line"></span> SELAMAT DATANG DI TAMAN TERAS</div><h1>Jeda sejenak.<br/>Nikmati yang <span>enak.</span></h1><p>Dari makanan rumahan sampai kopi favorit. Pilih menumu, kami siapkan dengan senang hati.</p><a href="#katalog" class="button primary">Pilih menu <Icon name="ArrowRight" :size="18"/></a><div class="operating"><span :class="['status-dot',{closed:!openNow}]"></span><strong>{{openNow?'Sedang buka':'Sedang tutup'}}</strong><span>Sen–Jum · 08.30–16.00 WIB</span></div></div>
      <div class="hero-image"><img src="/images/hero.jpg" alt="Ilustrasi secangkir kopi hangat di meja cafe" fetchpriority="high"/><div class="photo-scrim"></div><div class="image-label"><Icon name="Coffee" :size="23"/><span>Satu meja.<br/><strong>Banyak cerita.</strong></span></div><span class="image-caption">FOTO ILUSTRASI</span></div>
    </section>
    <section class="order-context" aria-label="Pengaturan pesanan"><div class="context-icon"><Icon name="Store" :size="22"/></div><div><strong>Mau dinikmati di mana?</strong><p>Pilih tipe pesanan sebelum mulai.</p></div><div class="context-controls"><div class="segmented"><button :class="{active:state.orderType==='dine_in'}" @click="state.orderType='dine_in'"><Icon name="UtensilsCrossed" :size="16"/>Dine-in</button><button :class="{active:state.orderType==='takeaway'}" @click="state.orderType='takeaway'"><Icon name="ShoppingBag" :size="16"/>Takeaway</button></div><label v-if="state.orderType==='dine_in'" class="table-select">Meja<select v-model="state.table" aria-label="Nomor meja"><option v-for="n in 50" :key="n" :value="n">{{String(n).padStart(2,'0')}}</option></select></label></div></section>
    <section id="katalog" class="catalog-section"><div class="section-title"><div><h2>Menu untuk setiap selera<span>.</span></h2><p>Pilih yang kamu suka. Jangan lupa minumnya.</p></div><span class="menu-count">{{menus.length}} pilihan menu</span></div>
      <div class="catalog-layout"><div class="catalog-main"><div class="category-tabs" aria-label="Kategori menu"><button v-for="item in categories" :key="item.id" :class="{active:category===item.id}" :aria-pressed="category===item.id" @click="category=item.id"><Icon :name="item.icon" :size="17"/>{{item.name}}<span>{{item.id==='all'?menus.length:menus.filter(x=>x.category===item.id).length}}</span></button></div>
        <div v-if="loading" class="menu-grid"><div v-for="n in 6" :key="n" class="skeleton menu-skeleton" aria-label="Memuat menu"></div></div>
        <div v-else-if="error" class="empty-state"><Icon name="AlertCircle" :size="32"/><h3>Menu belum bisa dimuat</h3><p>{{error}}</p><button class="button secondary" @click="load">Coba lagi</button></div>
        <div v-else-if="!filtered.length" class="empty-state"><Icon name="UtensilsCrossed" :size="32"/><h3>Belum ada menu</h3><p>Menu pada kategori ini akan segera tersedia.</p></div>
        <div v-else class="menu-grid"><article v-for="menu in filtered" :key="menu.id" :class="['menu-card',{unavailable:!menu.available}]"><div class="menu-photo"><img v-if="menu.image_url" :src="menu.image_url" :alt="menu.name+' (foto ilustrasi)'" loading="lazy" @error="$event.target.style.display='none'"/><Icon v-else name="UtensilsCrossed" :size="40"/><span v-if="!menu.available" class="menu-badge sold">Sedang habis</span><span v-else-if="menu.best_seller" class="menu-badge"><Icon name="Flame" :size="12"/>Favorit Teras</span></div><div class="menu-body"><div class="menu-category">{{menu.category}}<span v-if="menu.calories!==null">· ± {{menu.calories}} kkal</span></div><h3>{{menu.name}}</h3><p>{{menu.description}}</p><div class="menu-flavor"><span v-if="menu.spicy"><Icon name="Flame" :size="12"/>Pedas</span><span v-else>Tidak pedas</span></div><div class="menu-bottom"><strong>{{money(menu.price)}}</strong><Quantity v-if="quantity(menu.id)&&menu.available" :quantity="quantity(menu.id)" :name="menu.name" @change="changeQuantity(menu.id,$event)"/><button v-else class="add-button" :disabled="!menu.available" :aria-label="`Tambah ${menu.name} ke keranjang`" @click="addToCart(menu)"><Icon name="Plus" :size="17"/>Tambah</button></div></div></article></div>
        <p class="catalog-footnote"><Icon name="Info" :size="14"/>Foto dan kalori pada data contoh hanya ilustrasi. Tanyakan informasi alergi kepada staf.</p>
      </div>
      <aside class="cart-preview"><div class="cart-preview-title"><Icon name="ShoppingBag"/><h3>Pesananmu</h3><span>{{cartCount}}</span></div><template v-if="!cartCount"><div class="cart-empty"><div class="bag-circle"><Icon name="ShoppingBag" :size="30"/></div><strong>Masih kosong, nih.</strong><p>Tambahkan menu favoritmu.<br/>Jeda yang enak dimulai di sini.</p></div><div class="cart-help"><Icon name="Leaf" :size="17"/><span>Dibuat saat kamu pesan,<br/>dinikmati selagi hangat.</span></div></template><template v-else><div class="preview-items"><div v-for="item in state.cart" :key="item.id" class="preview-item"><div><strong>{{item.name}}</strong><span>{{money(item.price)}}</span></div><Quantity :quantity="item.quantity" :name="item.name" @change="changeQuantity(item.id,$event)"/></div></div><div class="preview-total"><span>Total</span><strong>{{money(cartTotal)}}</strong></div><RouterLink to="/checkout" class="button primary full">Lanjut checkout <Icon name="ArrowRight" :size="17"/></RouterLink><p class="secure-note">Bayar lewat QRIS atau transfer</p></template></aside></div>
    </section>
    <RouterLink v-if="cartCount" class="mobile-cart-bar" to="/checkout"><span><Icon name="ShoppingBag"/>{{cartCount}} item · {{money(cartTotal)}}</span><strong>Checkout <Icon name="ArrowRight" :size="17"/></strong></RouterLink>
  </div>
</template>
